import{_ as a,o,c as t,a2 as r}from"./chunks/framework.Wk4ah3nE.js";const p=JSON.parse('{"title":"FAQ","description":"Frequently asked questions about Proxmox VM Autoscale — scope, safety, tuning, LXC support, clustering and production readiness.","frontmatter":{"title":"FAQ","description":"Frequently asked questions about Proxmox VM Autoscale — scope, safety, tuning, LXC support, clustering and production readiness.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/faq.html"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/faq.html"}],["meta",{"property":"og:title","content":"FAQ"}],["meta",{"property":"og:description","content":"Frequently asked questions about Proxmox VM Autoscale — scope, safety, tuning, LXC support, clustering and production readiness."}]]},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":null}'),s={name:"guide/faq.md"};function n(i,e,h,d,l,c){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><h3 id="does-it-work-with-lxc-containers" tabindex="-1">Does it work with LXC containers? <a class="header-anchor" href="#does-it-work-with-lxc-containers" aria-label="Permalink to &quot;Does it work with LXC containers?&quot;">​</a></h3><p>No. It drives <code>qm</code>, which is QEMU/KVM only. Use <a href="https://github.com/fabriziosalmi/proxmox-lxc-autoscale" target="_blank" rel="noreferrer">proxmox-lxc-autoscale</a> for containers, or <a href="https://github.com/fabriziosalmi/proxmox-lxc-autoscale-ml" target="_blank" rel="noreferrer">proxmox-lxc-autoscale-ml</a> for the ML-driven variant.</p><h3 id="can-it-create-or-destroy-vms" tabindex="-1">Can it create or destroy VMs? <a class="header-anchor" href="#can-it-create-or-destroy-vms" aria-label="Permalink to &quot;Can it create or destroy VMs?&quot;">​</a></h3><p>No. It only resizes VMs you list explicitly. No cloning, no migration, no provisioning.</p><h3 id="can-it-scale-disk-or-network" tabindex="-1">Can it scale disk or network? <a class="header-anchor" href="#can-it-scale-disk-or-network" aria-label="Permalink to &quot;Can it scale disk or network?&quot;">​</a></h3><p>No. CPU cores, vCPUs and memory only.</p><h3 id="does-it-need-an-agent-inside-the-guest" tabindex="-1">Does it need an agent inside the guest? <a class="header-anchor" href="#does-it-need-an-agent-inside-the-guest" aria-label="Permalink to &quot;Does it need an agent inside the guest?&quot;">​</a></h3><p>No. Everything is read from the hypervisor. For memory changes to apply live the guest does need the <strong>virtio balloon driver</strong>, but that is a driver, not an agent.</p><h3 id="does-it-use-the-proxmox-api" tabindex="-1">Does it use the Proxmox API? <a class="header-anchor" href="#does-it-use-the-proxmox-api" aria-label="Permalink to &quot;Does it use the Proxmox API?&quot;">​</a></h3><p>No. It SSHes in and runs <code>qm</code> and <code>pvesh</code> as shell commands. There is no API token and no <code>pvesh</code> REST client — <code>pvesh</code> here is the CLI.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><h3 id="must-it-run-on-a-proxmox-node" tabindex="-1">Must it run on a Proxmox node? <a class="header-anchor" href="#must-it-run-on-a-proxmox-node" aria-label="Permalink to &quot;Must it run on a Proxmox node?&quot;">​</a></h3><p>No. Anywhere with SSH access to your nodes works, and running it off-node means a node reboot does not take the autoscaler with it. The installer assumes on-node because that is the common case.</p><h3 id="can-one-instance-manage-several-nodes" tabindex="-1">Can one instance manage several nodes? <a class="header-anchor" href="#can-one-instance-manage-several-nodes" aria-label="Permalink to &quot;Can one instance manage several nodes?&quot;">​</a></h3><p>Yes — list them all under <code>proxmox_hosts</code>. They are processed sequentially in one cycle.</p><h3 id="does-it-work-on-a-proxmox-cluster" tabindex="-1">Does it work on a Proxmox cluster? <a class="header-anchor" href="#does-it-work-on-a-proxmox-cluster" aria-label="Permalink to &quot;Does it work on a Proxmox cluster?&quot;">​</a></h3><p>It works on the nodes of a cluster, treating each as an independent host. It has no cluster awareness: no quorum check, no migration, no cluster-wide capacity view.</p><h3 id="can-i-use-an-ed25519-ssh-key" tabindex="-1">Can I use an Ed25519 SSH key? <a class="header-anchor" href="#can-i-use-an-ed25519-ssh-key" aria-label="Permalink to &quot;Can I use an Ed25519 SSH key?&quot;">​</a></h3><p>Not currently. The key file is loaded specifically as an RSA key. Use an RSA key or password authentication — see <a href="/proxmox-vm-autoscale/reference/limitations.html#only-rsa-ssh-keys-are-supported">known limitations</a>.</p><h3 id="does-it-need-root-on-the-proxmox-host" tabindex="-1">Does it need root on the Proxmox host? <a class="header-anchor" href="#does-it-need-root-on-the-proxmox-host" aria-label="Permalink to &quot;Does it need root on the Proxmox host?&quot;">​</a></h3><p>In practice yes. Every action is <code>qm</code> or <code>pvesh</code>, which require privileges a normal user does not have. There is no least-privilege mode; the <a href="/proxmox-vm-autoscale/security/">threat model</a> is honest about what that means.</p><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><h3 id="how-fast-does-it-react" tabindex="-1">How fast does it react? <a class="header-anchor" href="#how-fast-does-it-react" aria-label="Permalink to &quot;How fast does it react?&quot;">​</a></h3><p>At worst one <code>check_interval</code> (default 300 s) before a spike is even noticed, then one step per <code>scale_cooldown</code>. Going from 2 to 8 cores takes six steps. This is not a service for reacting to a traffic spike in seconds.</p><h3 id="can-i-make-the-steps-bigger" tabindex="-1">Can I make the steps bigger? <a class="header-anchor" href="#can-i-make-the-steps-bigger" aria-label="Permalink to &quot;Can I make the steps bigger?&quot;">​</a></h3><p>Not through configuration. Step sizes are fixed at 1 core and 512 MB in <code>vm_manager.py</code>.</p><h3 id="can-i-set-different-thresholds-per-vm" tabindex="-1">Can I set different thresholds per VM? <a class="header-anchor" href="#can-i-set-different-thresholds-per-vm" aria-label="Permalink to &quot;Can I set different thresholds per VM?&quot;">​</a></h3><p>No. <code>config.yaml</code> shows a <code>thresholds:</code> block inside each VM entry, but the code reads only the global <code>scaling_thresholds</code>. The per-VM block is inert. See <a href="/proxmox-vm-autoscale/reference/limitations.html#per-vm-thresholds-are-ignored">known limitations</a>.</p><h3 id="what-happens-if-the-service-is-restarted-mid-cooldown" tabindex="-1">What happens if the service is restarted mid-cooldown? <a class="header-anchor" href="#what-happens-if-the-service-is-restarted-mid-cooldown" aria-label="Permalink to &quot;What happens if the service is restarted mid-cooldown?&quot;">​</a></h3><p>The cooldown is forgotten. Timers are in memory only, so the first cycle after a restart can scale immediately.</p><h3 id="does-it-scale-vms-that-are-powered-off" tabindex="-1">Does it scale VMs that are powered off? <a class="header-anchor" href="#does-it-scale-vms-that-are-powered-off" aria-label="Permalink to &quot;Does it scale VMs that are powered off?&quot;">​</a></h3><p>No — a stopped guest is skipped before anything else happens.</p><h3 id="what-if-a-vm-s-usage-cannot-be-read" tabindex="-1">What if a VM&#39;s usage cannot be read? <a class="header-anchor" href="#what-if-a-vm-s-usage-cannot-be-read" aria-label="Permalink to &quot;What if a VM&#39;s usage cannot be read?&quot;">​</a></h3><p>It is treated as <code>0.0%</code>, which is below any sane <code>low</code> threshold, so the VM is scaled <strong>down</strong>. This is a genuine hazard, not a design choice — watch for <code>CPU usage not found in output</code> in the log.</p><h3 id="does-it-undo-its-changes-when-stopped" tabindex="-1">Does it undo its changes when stopped? <a class="header-anchor" href="#does-it-undo-its-changes-when-stopped" aria-label="Permalink to &quot;Does it undo its changes when stopped?&quot;">​</a></h3><p>No. Guests stay wherever the last scaling action left them, including any <code>hotplug</code> and <code>numa</code> flags the service set.</p><h2 id="tuning" tabindex="-1">Tuning <a class="header-anchor" href="#tuning" aria-label="Permalink to &quot;Tuning&quot;">​</a></h2><h3 id="good-starting-thresholds" tabindex="-1">Good starting thresholds? <a class="header-anchor" href="#good-starting-thresholds" aria-label="Permalink to &quot;Good starting thresholds?&quot;">​</a></h3><p>The shipped 20/80 for CPU and 25/85 for RAM are sensible. The important thing is the width of the gap, not the exact numbers — a narrow band causes oscillation.</p><h3 id="why-does-my-idle-vm-never-scale-down" tabindex="-1">Why does my idle VM never scale down? <a class="header-anchor" href="#why-does-my-idle-vm-never-scale-down" aria-label="Permalink to &quot;Why does my idle VM never scale down?&quot;">​</a></h3><p>An idle guest is rarely at 0% CPU: background daemons, cron, monitoring agents typically keep it at 3–10%. If your <code>low</code> is 20 and the guest idles at 22, it never crosses. Watch a few cycles of <code>VM 101 current usage</code> lines and set <code>low</code> below the observed floor.</p><h3 id="why-does-everything-scale-down-at-once-after-a-restart" tabindex="-1">Why does everything scale down at once after a restart? <a class="header-anchor" href="#why-does-everything-scale-down-at-once-after-a-restart" aria-label="Permalink to &quot;Why does everything scale down at once after a restart?&quot;">​</a></h3><p>Cooldowns are cleared on restart, so every VM is immediately eligible. If several are below their <code>low</code> threshold they all step down in the first cycle. That is expected — but if it happens on a busy fleet, check for the <code>usage not found</code> warnings first.</p><h3 id="should-scale-cooldown-be-shorter-than-check-interval" tabindex="-1">Should <code>scale_cooldown</code> be shorter than <code>check_interval</code>? <a class="header-anchor" href="#should-scale-cooldown-be-shorter-than-check-interval" aria-label="Permalink to &quot;Should `scale_cooldown` be shorter than `check_interval`?&quot;">​</a></h3><p>There is no point. Decisions only happen at poll time, so the effective interval is <code>max(check_interval, scale_cooldown)</code>.</p><h2 id="safety" tabindex="-1">Safety <a class="header-anchor" href="#safety" aria-label="Permalink to &quot;Safety&quot;">​</a></h2><h3 id="can-it-take-a-host-down" tabindex="-1">Can it take a host down? <a class="header-anchor" href="#can-it-take-a-host-down" aria-label="Permalink to &quot;Can it take a host down?&quot;">​</a></h3><p><code>host_limits</code> is designed to prevent that: no VM on a node above its ceiling gets scaled. The gate also blocks scale-<em>down</em>, though, so a saturated node cannot shrink its idle guests either.</p><h3 id="can-it-break-a-running-vm" tabindex="-1">Can it break a running VM? <a class="header-anchor" href="#can-it-break-a-running-vm" aria-label="Permalink to &quot;Can it break a running VM?&quot;">​</a></h3><p>Realistically, the two risks are memory and CPU removal. Ballooning memory away from a guest that is genuinely using it can push it into swap or trigger the OOM killer — keep <code>min_ram_mb</code> at a value the workload actually survives. Removing a vCPU is unreliable on some guests, Windows especially.</p><h3 id="is-there-a-dry-run-mode" tabindex="-1">Is there a dry-run mode? <a class="header-anchor" href="#is-there-a-dry-run-mode" aria-label="Permalink to &quot;Is there a dry-run mode?&quot;">​</a></h3><p>No. If the service is running and a threshold is crossed, the command is executed. The nearest approximation is <code>scaling_enabled: false</code> on every VM, which produces the monitoring log lines with no actions.</p><h3 id="is-it-safe-for-production" tabindex="-1">Is it safe for production? <a class="header-anchor" href="#is-it-safe-for-production" aria-label="Permalink to &quot;Is it safe for production?&quot;">​</a></h3><p>It is a small single-process service with 114 unit tests, run by its author and by others across 302 stars and 23 forks. It is also alpha-versioned software that holds root credentials, has no dry-run, and has known defects documented on the <a href="/proxmox-vm-autoscale/reference/limitations.html">limitations</a> page. Read that page and the <a href="/proxmox-vm-autoscale/security/">threat model</a>, pilot it on VMs you can afford to disturb, and decide for yourself.</p><h2 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h2><h3 id="what-python-version" tabindex="-1">What Python version? <a class="header-anchor" href="#what-python-version" aria-label="Permalink to &quot;What Python version?&quot;">​</a></h3><p>3.9 or newer. CI tests 3.9 through 3.12.</p><h3 id="which-version-should-i-run" tabindex="-1">Which version should I run? <a class="header-anchor" href="#which-version-should-i-run" aria-label="Permalink to &quot;Which version should I run?&quot;">​</a></h3><p>The latest release, or <code>main</code>. Note that the tags are not in chronological order — <code>v1.2.0</code> predates <code>v0.1.1</code> despite the numbering. <code>v0.1.1</code> is the current release.</p><h3 id="how-do-i-report-a-bug-or-a-vulnerability" tabindex="-1">How do I report a bug or a vulnerability? <a class="header-anchor" href="#how-do-i-report-a-bug-or-a-vulnerability" aria-label="Permalink to &quot;How do I report a bug or a vulnerability?&quot;">​</a></h3><p>Bugs: <a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale/issues/new/choose" target="_blank" rel="noreferrer">GitHub issues</a>. Vulnerabilities: <strong>not</strong> as a public issue — see <a href="/proxmox-vm-autoscale/security/disclosure.html">reporting a vulnerability</a>.</p><h3 id="is-commercial-support-available" tabindex="-1">Is commercial support available? <a class="header-anchor" href="#is-commercial-support-available" aria-label="Permalink to &quot;Is commercial support available?&quot;">​</a></h3><p>Yes. Paid support, custom development and consulting around infrastructure automation, hardening and monitoring: <strong><a href="mailto:fabrizio.salmi@gmail.com" target="_blank" rel="noreferrer">fabrizio.salmi@gmail.com</a></strong>.</p>',65)])])}const m=a(s,[["render",n]]);export{p as __pageData,m as default};
